import React, { useEffect, useState } from "react";
import Layout from "../components/Layout";
import api from "../services/api";
import { useParams } from "react-router-dom";

const Prescription = () => {
    const { phone } = useParams(); // from Patients page

    // ✅ Patient List from DB
    const [patients, setPatients] = useState([]);

    // ✅ Form Data
    const [formData, setFormData] = useState({
        name: "",
        phone: "",
        medicines: [{ medicine: "", dosage: "", days: "" }],
    });

    // =====================================================
    // ✅ Fetch Patients from DB
    // =====================================================
    const fetchPatients = async () => {
        try {
            const res = await api.get("/patients");
            setPatients(res.data);

            // ✅ Auto Select Patient if phone passed
            if (phone) {
                const selected = res.data.find((p) => p.phone === phone);

                if (selected) {
                    setFormData((prev) => ({
                        ...prev,
                        name: selected.name,
                        phone: selected.phone,
                    }));
                }
            }
        } catch (error) {
            console.log("Error fetching patients:", error);
        }
    };

    useEffect(() => {
        fetchPatients();
    }, []);

    // =====================================================
    // ✅ Handle Patient Dropdown Change
    // =====================================================
    const handlePatientSelect = (e) => {
        const selectedPhone = e.target.value;

        const selectedPatient = patients.find(
            (p) => p.phone === selectedPhone
        );

        if (selectedPatient) {
            setFormData({
                ...formData,
                name: selectedPatient.name,
                phone: selectedPatient.phone,
            });
        }
    };

    // =====================================================
    // ✅ Handle Medicine Row Change
    // =====================================================
    const handleMedicineChange = (index, field, value) => {
        const updatedMedicines = [...formData.medicines];
        updatedMedicines[index][field] = value;

        setFormData({
            ...formData,
            medicines: updatedMedicines,
        });
    };

    // =====================================================
    // ✅ Add New Medicine Row
    // =====================================================
    const addMedicineRow = () => {
        setFormData({
            ...formData,
            medicines: [...formData.medicines, { medicine: "", dosage: "", days: "" }],
        });
    };

    // =====================================================
    // ✅ Remove Medicine Row
    // =====================================================
    const removeMedicineRow = (index) => {
        const updatedMedicines = formData.medicines.filter(
            (_, i) => i !== index
        );

        setFormData({
            ...formData,
            medicines: updatedMedicines,
        });
    };

    // =====================================================
    // ✅ Save Prescription + Generate PDF
    // =====================================================
    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            // ✅ Save Prescription in DB
            await api.post("/prescription", formData);

            // ✅ Generate PDF Prescription
            const res = await api.post("/prescription/pdf", formData, {
                responseType: "blob",
            });

            // Download PDF
            const file = new Blob([res.data], { type: "application/pdf" });
            const link = document.createElement("a");
            link.href = window.URL.createObjectURL(file);
            link.download = "prescription.pdf";
            link.click();

            alert("✅ Prescription Saved + PDF Generated Successfully");

            // Reset Medicines Only
            setFormData({
                ...formData,
                medicines: [{ medicine: "", dosage: "", days: "" }],
            });
        } catch (error) {
            console.log("Error:", error);
            alert("❌ Failed to Generate Prescription");
        }
    };

    return (
        <Layout>
            <div className="container-fluid">

                {/* Page Header */}
                <h2 className="fw-bold mb-4 text-primary">
                    💊 Prescription Generator
                </h2>

                <div className="card shadow-lg border-0">
                    <div className="card-header bg-primary text-white fw-bold">
                        Create Prescription PDF
                    </div>

                    <div className="card-body">
                        <form onSubmit={handleSubmit}>

                            {/* ✅ Patient Dropdown */}
                            <div className="mb-3">
                                <label className="form-label fw-semibold">
                                    Select Patient
                                </label>

                                <select
                                    className="form-select"
                                    value={formData.phone}
                                    onChange={handlePatientSelect}
                                    required
                                >
                                    <option value="">-- Select Patient --</option>

                                    {patients.map((p) => (
                                        <option key={p._id} value={p.phone}>
                                            {p.name} ({p.phone})
                                        </option>
                                    ))}
                                </select>
                            </div>

                            {/* Medicines Section */}
                            <h5 className="fw-bold mt-4 mb-3">
                                💊 Medicines List
                            </h5>

                            {formData.medicines.map((med, index) => (
                                <div
                                    key={index}
                                    className="row g-2 mb-2 align-items-center"
                                >
                                    {/* Medicine */}
                                    <div className="col-md-4">
                                        <input
                                            type="text"
                                            className="form-control"
                                            placeholder="Medicine Name"
                                            value={med.medicine}
                                            onChange={(e) =>
                                                handleMedicineChange(index, "medicine", e.target.value)
                                            }
                                            required
                                        />
                                    </div>

                                    {/* Dosage */}
                                    <div className="col-md-3">
                                        <input
                                            type="text"
                                            className="form-control"
                                            placeholder="Dosage (1-0-1)"
                                            value={med.dosage}
                                            onChange={(e) =>
                                                handleMedicineChange(index, "dosage", e.target.value)
                                            }
                                            required
                                        />
                                    </div>

                                    {/* Days */}
                                    <div className="col-md-3">
                                        <input
                                            type="number"
                                            className="form-control"
                                            placeholder="Days"
                                            value={med.days}
                                            onChange={(e) =>
                                                handleMedicineChange(index, "days", e.target.value)
                                            }
                                            required
                                        />
                                    </div>

                                    {/* Remove */}
                                    <div className="col-md-2">
                                        {formData.medicines.length > 1 && (
                                            <button
                                                type="button"
                                                className="btn btn-danger w-100"
                                                onClick={() => removeMedicineRow(index)}
                                            >
                                                ❌ Remove
                                            </button>
                                        )}
                                    </div>
                                </div>
                            ))}

                            {/* Add Medicine */}
                            <button
                                type="button"
                                className="btn btn-outline-primary mt-3"
                                onClick={addMedicineRow}
                            >
                                ➕ Add Another Medicine
                            </button>

                            {/* Submit */}
                            <div className="text-end mt-4">
                                <button type="submit" className="btn btn-success px-4">
                                    📄 Save + Generate PDF
                                </button>
                            </div>

                        </form>
                    </div>
                </div>

            </div>
        </Layout>
    );
};

export default Prescription;
